
INSERT INTO quiz_questions (course_id, question, options, correct_answer, explanation) VALUES
-- Week 1: Concept of Entrepreneurship
('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'What is entrepreneurship?', '["The process of identifying opportunities, mobilizing resources, creating innovative products or services and taking risks to generate value and achieve profit", "The process of managing an existing company", "The act of investing in stocks and bonds", "The process of government regulation of businesses"]', 0, 'Entrepreneurship is defined as the process of identifying opportunities, mobilizing resources, creating innovative products or services and taking risks to generate value and achieve profit.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'According to the course material, the formula for entrepreneurship is:', '["Opportunity + Innovation + Value Creation + Risk", "Capital + Labour + Management + Profit", "Idea + Funding + Marketing + Sales", "Planning + Execution + Control + Evaluation"]', 0, 'The material states: Entrepreneurship = Opportunity + Innovation + Value Creation + Risk.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which of the following is an example of Social Entrepreneurship mentioned in the material?', '["Paystack", "Leap Africa", "Dangote Cement", "Flutterwave"]', 1, 'Leap Africa is cited as an example of social entrepreneurship, tackling youth development challenges.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Paystack is used as an example of which scope of entrepreneurship?', '["Social Entrepreneurship", "Green Entrepreneurship", "Technological Entrepreneurship", "Corporate Entrepreneurship"]', 2, 'Paystack is cited as an example of technological entrepreneurship, revolutionizing digital payments.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which of the following is an example of Corporate Entrepreneurship?', '["Dangote Cement", "MTN MoMo and Gmail at Google", "FarmCrowdy", "Konga"]', 1, 'Corporate entrepreneurship involves innovative activities carried out inside large organisations. MTN MoMo and Gmail at Google are examples.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'What is a Vision Statement?', '["A list of company products", "A forward-looking declaration that expresses the ultimate goal or dream of the business", "A financial report for investors", "A marketing strategy document"]', 1, 'A Vision Statement is defined as a forward-looking declaration that expresses the ultimate goal or dream of the business.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which entrepreneur started a small trading business with a loan from his uncle at 21 years old?', '["Tony Elumelu", "Sim Shagaya", "Aliko Dangote", "Jason Njoku"]', 2, 'Aliko Dangote from Kano State started a small trading business at 21 with a loan from his uncle.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Green/Environmental Entrepreneurship focuses on:', '["Maximizing profit at all costs", "Developing solutions that protect the environment or promote sustainability", "Government regulation of industries", "International trade agreements"]', 1, 'Green/Environmental Entrepreneurship involves developing solutions that protect the environment or promote sustainability, e.g., Sahara Energy Renewable Project.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'International Entrepreneurship involves:', '["Only domestic business operations", "Activities across national borders including exporting, expansion and foreign partnership", "Government-run businesses", "Non-profit charitable organizations"]', 1, 'International Entrepreneurship involves activities across national borders - exporting, expansion & foreign partnership. Dangote Cement in 10 African countries is an example.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Public Sector Entrepreneurship examples include:', '["Paystack and Flutterwave", "Digital tax collection systems and online passport application portals", "Nollywood films", "Instagram vendors"]', 1, 'Public sector entrepreneurship involves innovating within public agencies to improve service delivery, such as digital tax collection systems and online passport application portals.'),

-- Dimensions of Entrepreneurship
('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which dimension of entrepreneurship involves creating something new or improving existing products, services or processes?', '["Proactiveness", "Risk Taking", "Innovativeness", "Autonomy"]', 2, 'Innovativeness means creating something new or improving existing products, services or processes. Flutterwave created an innovative payment infrastructure.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Proactiveness in entrepreneurship means:', '["Waiting for opportunities to come", "Anticipating future trends, acting ahead of competitors, and seizing opportunity early", "Avoiding all forms of risk", "Following what competitors do"]', 1, 'Proactiveness means entrepreneurs anticipate future trends, act ahead of competitors, and seize opportunity early. Sim Shagaya pioneered Konga (e-commerce).'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which entrepreneur is associated with Resource Mobilisation and turning UBA into a global bank?', '["Aliko Dangote", "Sim Shagaya", "Tony Elumelu", "Jason Njoku"]', 2, 'Tony Elumelu turned UBA into a global bank as an example of resource mobilisation.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'FarmCrowdy is used as an example of which dimension of entrepreneurship?', '["Risk Taking", "Autonomy", "Value Creation", "Proactiveness"]', 2, 'FarmCrowdy connected farmers with digital funding and agricultural support, which is an example of value creation.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Opportunity Recognition in entrepreneurship begins with:', '["Having a large capital base", "Identifying unmet needs, market gaps or solutions to problems", "Copying what competitors are doing", "Getting government approval"]', 1, 'Entrepreneurship begins with identifying unmet needs, market gap or solutions to problems.'),

-- Week 2&3: Entrepreneurial Traits
('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'The ability to identify and capitalize on market gaps or unmet needs describes which entrepreneurial trait?', '["The Problem Solver", "The Calculated Risk-Taker", "The Opportunity Seeker", "The Change Agent"]', 2, 'The Opportunity Seeker is described as having the ability to identify and capitalize on market gaps or unmet needs.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Sim Shagaya founded which Nigerian e-commerce platform?', '["Jumia", "Konga", "Flutterwave", "Paystack"]', 1, 'Sim Shagaya saw the low penetration of formal retail and growing internet use in Nigeria, leading him to found Konga.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'According to the material, entrepreneurial risk is about:', '["Eliminating all uncertainty", "Managing uncertainty, not eliminating it", "Avoiding all risky ventures", "Only investing in guaranteed returns"]', 1, 'The material states that entrepreneurial risk is about managing uncertainty, not eliminating it.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Dr. Oluwayemisi (DentistAtYourDoor) is an example of which entrepreneurial trait?', '["The Opportunity Seeker", "The Calculated Risk-Taker", "The Problem Solver and Change Agent", "The Innovator"]', 2, 'Dr. Oluwayemisi solved the problem of dental care access in traffic-heavy Lagos by launching the first mobile dental clinic, making her both a problem solver and change agent.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Chinedu Azodoh (MAX.ng) solved which problem?', '["Lack of internet access", "Unsafe, informal motorcycle taxis (okada)", "Expensive food delivery", "Poor banking services"]', 1, 'MAX.ng solved the problem of unsafe, informal motorcycle taxis (okada) by creating a tech-enabled, safer ride-hailing and delivery service.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'The Igbo Apprenticeship System (Igba Boi) is described as:', '["A government training program", "The world''s largest business incubator", "A university curriculum", "A foreign exchange program"]', 1, 'The Igbo Apprenticeship System (Igba Boi) is described as the world''s largest business incubator right in Nigeria.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'In the Igba Boi system, what happens at the final stage?', '["The apprentice is fired", "The apprentice is settled (funded) to start their own business", "The apprentice becomes an employee permanently", "The apprentice goes back to school"]', 1, 'In Igba Boi, young people are picked, nurtured through years of mentorship, and then settled (funded) to start their own business.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'What does the "Nurtured Traits (Made)" argument for entrepreneurship emphasize?', '["Natural charisma and energy from birth", "Skills developed through education, mentorship, accounting, and experience", "Genetic predisposition to business", "Luck and timing"]', 1, 'The Nurtured argument emphasizes that skills like emotional management, marketing, and intelligence are learned skills developed through education, mentorship, and experience.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'According to the material, the difference between creativity and innovation is:', '["They are the same thing", "Creativity involves having a better idea and innovation involves making it a reality", "Innovation comes first, then creativity", "Creativity is for artists only"]', 1, 'The material states that creativity involves having a better idea and innovation involves making it a reality.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Jason Njoku (iROKOtv) revolutionized Nollywood by:', '["Building movie theatres", "Moving content distribution online, solving piracy and access issues", "Creating a record label", "Starting a newspaper"]', 1, 'Jason Njoku revolutionized Nollywood content distribution by moving it online, solving piracy and access issues.'),

-- Week 4&5: Innovation and Change
('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Innovation is defined as:', '["Just inventing something new", "The successful implementation of new ideas that create value", "Copying existing products", "Government policy on technology"]', 1, 'Innovation is the successful implementation of new ideas that create value. It''s not just invention; it''s about making an idea work in the real world.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'The Four Dimensions of Innovation include all EXCEPT:', '["Product Innovation", "Process Innovation", "Financial Innovation", "Organisational Innovation"]', 2, 'The four dimensions are Product Innovation (what you sell), Process Innovation (how you create it), Market Innovation (who you sell to), and Organisational Innovation (how you structure your company).'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Product Innovation refers to:', '["How you structure your company", "What you sell", "Who you sell to", "How you create it"]', 1, 'Product Innovation refers to what you sell - improving a product or creating a totally new one.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Process Innovation refers to:', '["What you sell", "Who you sell to", "Changing how a product is created or delivered to lower cost or increase speed", "How you structure your company"]', 2, 'Process Innovation means changing how a product is created or delivered to lower cost or increase speed. Chowdeck and Glovo using bikes for delivery is an example.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Cowrywise and Piggyvest are examples of which type of innovation?', '["Process Innovation", "Organisational Innovation", "Product Innovation", "Market Innovation"]', 2, 'They took the traditional wooden Kolo (savings box) and moved it to an app with interest rates - this is product innovation.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Organisational Innovation involves:', '["Creating new products", "Changing workplace culture or structure", "Finding new markets", "Changing delivery methods"]', 1, 'Organisational Innovation involves changing workplace culture or structure. Andela/Tech Startups moving to results-based remote work culture is an example.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'In the DIKW model, what does the "K" stand for?', '["Key", "Knowledge", "Kinetics", "Kingdom"]', 1, 'DIKW stands for Data, Information, Knowledge, Wisdom. Knowledge is the application of information.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'In the DIKW model, Data refers to:', '["Innovation and value creation", "Raw facts", "Application of information", "Creating value from knowledge"]', 1, 'Data refers to raw facts, e.g., "Rice is 80k per bag".'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Knowledge Management (KM) is:', '["The process of firing employees", "The systematic process of creating, sharing, using, and managing an organization''s knowledge and information", "A type of accounting system", "A government regulatory framework"]', 1, 'Knowledge Management is the systematic process of creating, sharing, using, and managing an organization''s knowledge and information.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Kurt Lewin''s Change Model consists of which three stages?', '["Plan, Do, Check", "Unfreeze, Change, Refreeze", "Start, Execute, Finish", "Analyze, Design, Implement"]', 1, 'Kurt Lewin''s Model consists of Unfreeze (realizing old way is bad), Change (transition to new way), and Refreeze (making new way the habit).'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'In Kurt Lewin''s model, the "Unfreeze" stage involves:', '["Making the new way a habit", "The messy transition period", "Realizing the old way is dangerous or expensive", "Evaluating results"]', 2, 'Unfreeze means realizing the old way (e.g., kerosene stoves) is dangerous or expensive - convincing people why the old way is bad.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'The fuel subsidy removal case study (2023/2024) led to which innovations?', '["New banking systems", "Companies shifted to remote work and mechanics converting cars to CNG", "New educational programs", "Social media platforms"]', 1, 'After fuel subsidy removal, companies shifted to remote work (Organisational Change) and mechanics started converting cars to CNG (Product/Process Change).'),

-- Week 6&7: Enterprise Formation
('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'A business plan is described as:', '["A marketing brochure", "A strategic roadmap detailing a company''s goals and the methods to achieve them", "An accounting ledger", "A legal contract"]', 1, 'A business plan serves as a strategic roadmap detailing a company''s goals and the methods to achieve them.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which of the following is NOT a core component of a simple business plan?', '["Executive Summary", "SWOT Analysis", "Employee vacation policy", "Revenue Model"]', 2, 'Core components include Executive Summary, Business Opportunity, Competitor Analysis, SWOT Analysis, Revenue Model, Financial Projection, and Team.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'SWOT Analysis stands for:', '["Sales, Wages, Operations, Taxes", "Strength, Weakness, Opportunities and Threats", "Strategy, Work, Objectives, Targets", "Supply, Wholesale, Output, Trade"]', 1, 'SWOT stands for Strength, Weakness, Opportunities and Threats.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'A Sole Proprietorship is characterized by:', '["Multiple owners sharing profits", "A single owner with unlimited personal liability for all debts", "Limited liability for the owner", "Democratic control by members"]', 1, 'A sole proprietorship has a single owner with no legal difference between the owner and the business, meaning unlimited personal liability.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'A Limited Liability Partnership (LLP) offers partners:', '["Unlimited personal liability", "Limited personal liability for business debts, protecting personal assets", "No legal identity", "Equal ownership with the government"]', 1, 'An LLP offers partners limited personal liability for business debts and obligations, protecting their personal assets.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'A General Partnership involves:', '["A single owner", "Two or more individuals sharing responsibilities, assets, profits, and liabilities", "Government ownership", "Public shareholders"]', 1, 'A general partnership is a business arrangement where two or more individuals agree to share responsibilities, assets, profits, and financial and legal liabilities.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'A Cooperative (co-op) is best described as:', '["A business owned by shareholders", "A business owned and democratically controlled by its members", "A government agency", "A franchise operation"]', 1, 'A cooperative is a business owned and democratically controlled by its members with equal voting rights (one member, one vote).'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which form of business ownership is best suited for solo vendors and freelancers?', '["General Partnership", "Limited Liability Company", "Sole Proprietorship", "Cooperative"]', 2, 'According to the comparison table, sole proprietorship is best for solo vendors and freelancers due to its simplicity, low cost, and full control.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which form of business ownership protects personal assets and is credible for investors?', '["Sole Proprietorship", "General Partnership", "Limited Liability Company (Ltd)", "Cooperative"]', 2, 'Limited Liability Company (Ltd) protects personal assets and is credible for investors, making it best for most scalable startups.'),

-- Week 8&9: Business Registration
('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Business registration in Nigeria is managed by:', '["Central Bank of Nigeria (CBN)", "Corporate Affairs Commission (CAC)", "Federal Inland Revenue Service (FIRS)", "Securities and Exchange Commission (SEC)"]', 1, 'Business registration in Nigeria is managed by the Corporate Affairs Commission (CAC) under CAMA.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Within how many days of starting a business must you register it in Nigeria?', '["7 days", "14 days", "28 days", "90 days"]', 2, 'Registering your business is a legal requirement within 28 days of starting.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'After CAC registration, you must obtain which document from FIRS?', '["Business License", "Tax Identification Number (TIN)", "Import License", "Operating Permit"]', 1, 'Post-registration, you must obtain a Tax Identification Number (TIN) from the Federal Inland Revenue Service (FIRS).'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which is a common registration pitfall to avoid?', '["Conducting a thorough name search", "Skipping the name search", "Registering early", "Using accurate information"]', 1, 'Skipping the name search is a common pitfall because conflicting names cause rejection.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'A Joint Venture (JV) is best described as:', '["An informal networking event", "A specific type of strategic alliance where partnering firms create a new, jointly owned, separate legal entity", "A sole proprietorship", "A government program"]', 1, 'A Joint Venture is a specific type of strategic alliance where partnering firms create a new, jointly owned, separate legal entity to pursue a shared objective.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'The Wintel alliance (Microsoft and Intel) is an example of:', '["Joint Venture", "Strategic Alliance", "General Partnership", "Cooperative"]', 1, 'The Wintel (Microsoft and Intel) alliance is cited as a famous example of a strategic alliance in the tech industry.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Networking in business is described as:', '["A formal legal agreement", "The informal process of building relationships and connections for potential future collaboration", "Creating a new company with partners", "A type of franchise agreement"]', 1, 'Networking is the informal process of building relationships and connections with other professionals for potential future collaboration and information exchange.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'According to the networking plan, you should follow up with a personalized message within:', '["24 hours", "48 hours", "1 week", "1 month"]', 1, 'The material advises to follow up with a personalized message within 48 hours after networking.'),

-- Week 10&11: Micro and Small Enterprise
('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'According to SMEDAN (2017), a micro enterprise has:', '["More than 50 employees", "Less than 10 employees and total assets not exceeding N5 million", "10-49 employees", "More than 100 employees"]', 1, 'SMEDAN defines micro enterprise as a business with less than 10 employees and total assets (excluding land and building) not exceeding N5 million.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'According to the World Bank (2020), micro enterprises are firms with:', '["Fewer than 5 employees", "Fewer than 10 employees", "10-49 employees", "50-100 employees"]', 1, 'World Bank (2020) defines micro enterprises as firms with fewer than 10 employees.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which is NOT a characteristic of micro enterprises?', '["Low Start-Up Capital", "Limited Use of Technology", "Better Access to Finance", "High Business Mortality Rate"]', 2, 'Better Access to Finance is a characteristic of small enterprises, not micro enterprises. Micro enterprises face challenges accessing bank loans.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'According to SMEDAN, a small enterprise is defined as having:', '["Less than 10 employees", "10-49 employees and total assets between N5 million and N49 million", "50-100 employees", "More than 100 employees"]', 1, 'SMEDAN defines a small enterprise as having 10-49 employees and total assets between N5 million and N49 million, excluding land and buildings.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'POS (Point of Sale) agency businesses are classified as which type of micro enterprise?', '["Service-Based", "Manufacturing and Craft", "Retail and Trading", "ICT and Creative"]', 2, 'POS agency businesses fall under Retail and Trading Micro Enterprises.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Which is a characteristic of small enterprises but NOT micro enterprises?', '["Owner-dependent operations", "Formal Business Registration", "Informal business structure", "High business mortality rate"]', 1, 'Formal Business Registration is a characteristic of small enterprises. Micro enterprises often operate without full registration.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Micro enterprises primarily serve which type of markets?', '["International markets", "National markets", "Local or community-based markets", "Government markets"]', 2, 'Micro enterprises serve local or community-based markets rather than national or international markets.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'The importance of micro and small businesses includes all EXCEPT:', '["Wealth creation", "Employment generation", "Increasing government bureaucracy", "Poverty reduction"]', 2, 'The importance includes wealth creation, employment generation, financial independence, and poverty reduction - not increasing government bureaucracy.'),

('ffc2d755-7d24-4dcc-bb51-734ef78e8a81', 'Market Innovation refers to:', '["How you create products", "Who you sell to and how you reach them", "How you structure your company", "What you sell"]', 1, 'Market Innovation refers to who you sell to and how you reach them - finding new markets or packaging for existing products.');
